INSERT INTO LIVROS_CATALOGO (TITULO, AUTOR, CRIADO_EM) SELECT MIN(TITULO), MAX(NULLIF(AUTOR, '')), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM VW_LOTE_NOMES WHERE CHAVE = '{{chave}}' AND CONF = 'alta' AND TITULO <> '' GROUP BY TITULO COLLATE utf8mb4_0900_ai_ci ON DUPLICATE KEY UPDATE AUTOR = COALESCE(LIVROS_CATALOGO.AUTOR, VALUES(AUTOR))